public static int tripleCount(int[] input) {
    int result = 0;
    for (int i = 0; i < input.length; i++)
        for (int j = 0; j < input.length; j++)
            for (int k = 0; k < input.length; k++)
                if (input[i] + input[j] + input[k] == 0) result++;
    return result;
}
